# Convert the SageMath weight format to omega basis tuples
def sage_wt_to_tuple(wt):
    """Convert a SageMath weight (in epsilon basis with sum=0) to omega basis."""
    # The SageMath weights are in the epsilon basis: (e1,e2,e3,e4) with e1+e2+e3+e4=0
    # Convert to omega basis: omega_i = e1+...+ei (i=1,2,3)
    # omega_1 = e1, omega_2 = e1+e2, omega_3 = e1+e2+e3
    # So in coroot coordinates: weight (a,b,c) in omega basis means
    # the weight is a*omega_1 + b*omega_2 + c*omega_3
    # The epsilon coordinates are:
    # e1 = (3a+2b+c)/4, e2 = (-a+2b+c)/4, e3 = (-a-2b+c)/4, e4 = (-a-2b-3c)/4
    # Conversely: a = e1-e2, b = e2-e3, c = e3-e4
    coords = list(wt)
    a = coords[_sage_const_0 ] - coords[_sage_const_1 ]
    b = coords[_sage_const_1 ] - coords[_sage_const_2 ]
    c = coords[_sage_const_2 ] - coords[_sage_const_3 ]
    # Need to convert to integers
    return (int(a*_sage_const_4 +_sage_const_1 /_sage_const_2 )//_sage_const_4  if isinstance(a, float) else int(a),
            int(b*_sage_const_4 +_sage_const_1 /_sage_const_2 )//_sage_const_4  if isinstance(b, float) else int(b),
            int(c*_sage_const_4 +_sage_const_1 /_sage_const_2 )//_sage_const_4  if isinstance(c, float) else int(c))

