# Build multiplicity lookup for each irrep
def build_eps_lookup(wm_dict):
    """Convert SageMath weight_multiplicities to epsilon-tuple -> mult lookup."""
    lookup = {}
    for wt, mult in wm_dict.items():
        key = tuple(wt)  # Already in epsilon basis from SageMath
        lookup[key] = mult
    return lookup

