def compute_proj_dims(x_weights):
    """Given a list of weights (from V tensor X), compute projection dims to each irrep."""
    # Count multiplicities of each weight in x_weights
    from collections import Counter
    wt_counts = Counter(x_weights)

    d36 = sum(min(count, lookup36.get(wt, _sage_const_0 )) for wt, count in wt_counts.items())
    d20 = sum(min(count, lookup20.get(wt, _sage_const_0 )) for wt, count in wt_counts.items())
    d4 = sum(min(count, lookup4.get(wt, _sage_const_0 )) for wt, count in wt_counts.items())
    return d36, d20, d4

